type View struct {
	Title    string    `json:"title,omitempty"`
	Sections []Section `json:"sections"`
	// The extension's own, sent back with the next render or action; at most 16 KB.
	State string `json:"state,omitempty"`
	// Draw again after this many seconds while on screen (30 at least; 0 never).
	RefreshAfter int     `json:"refresh_after,omitempty"`
	Search       *Search `json:"search,omitempty"`
	Filter       *Filter `json:"filter,omitempty"`
	Tabs         *Tabs   `json:"tabs,omitempty"`
	Layout       string  `json:"layout,omitempty"`
	Review       *Review `json:"review,omitempty"`
	// Plain text for an assistant card: required by CheckAssistantView; not required for extension views.
	Fallback string `json:"fallback,omitempty"`
	// Assistant card details keyed by page name; at most 8. A detail page cannot contain pages itself. Push.page refers
	// to this root map.
	Pages map[string]View `json:"pages,omitempty"`
}

type Section struct {
	// Stable section identity in stream protocol 1 (UI version 7); optional for legacy snapshots.
	Key    string      `json:"key,omitempty"`
	Title  string      `json:"title,omitempty"`
	Footer string      `json:"footer,omitempty"`
	Items  []Component `json:"items"`
	More   *More       `json:"more,omitempty"`
	Pane   string      `json:"pane,omitempty"`
	Span   string      `json:"span,omitempty"`
	// Drawn before the title.
	Icon      string       `json:"icon,omitempty"`
	IconColor string       `json:"icon_color,omitempty"`
	Link      *SectionLink `json:"link,omitempty"`
	// How many rows sit side by side in the section on a wide screen (UI version 8), in reading order; one on a narrow
	// screen and when absent. Other components keep the whole width.
	Columns int `json:"columns,omitempty"`
}

// Component: one component of a view, told apart by type. A type an app does not know is skipped and the rest drawn.
// One struct for every variant: type says which fields mean something.
type Component struct {
	Type      string     `json:"type"`
	Key       string     `json:"key,omitempty"`
	Text      string     `json:"text,omitempty"`
	Style     string     `json:"style,omitempty"`
	Label     string     `json:"label,omitempty"`
	Value     string     `json:"value,omitempty"`
	Detail    string     `json:"detail,omitempty"`
	Tone      string     `json:"tone,omitempty"`
	Icon      string     `json:"icon,omitempty"`
	IconColor string     `json:"icon_color,omitempty"`
	Spark     *Spark     `json:"spark,omitempty"`
	Ratio     *float64   `json:"ratio,omitempty"`
	Title     string     `json:"title,omitempty"`
	Subtitle  string     `json:"subtitle,omitempty"`
	Badge     *Badge     `json:"badge,omitempty"`
	Action    *Action    `json:"action,omitempty"`
	Avatar    *Avatar    `json:"avatar,omitempty"`
	Thumbnail *Thumbnail `json:"thumbnail,omitempty"`
	// A switch, a slider or a stepper; the row then has a key.
	Control *RowControl `json:"control,omitempty"`
	// Extra actions in the row's menu and under a swipe: shortcuts only, the same must be possible on the page the row
	// opens.
	Actions     []RowAction `json:"actions,omitempty"`
	Role        string      `json:"role,omitempty"`
	URL         string      `json:"url,omitempty"`
	Name        string      `json:"name,omitempty"`
	Kind        string      `json:"kind,omitempty"`
	Choices     []Choice    `json:"choices,omitempty"`
	Placeholder string      `json:"placeholder,omitempty"`
	// date, time, datetime: the first one allowed, written like value.
	Earliest string `json:"earliest,omitempty"`
	// date, time, datetime: the last one allowed.
	Latest  string        `json:"latest,omitempty"`
	Series  []ChartSeries `json:"series,omitempty"`
	Unit    string        `json:"unit,omitempty"`
	Stacked bool          `json:"stacked,omitempty"`
	// donut: the words in the hole (a total).
	Center string `json:"center,omitempty"`
	// candlestick: the color of a rising candle.
	Rising    string        `json:"rising,omitempty"`
	Stats     []Stat        `json:"stats,omitempty"`
	Columns   []TableColumn `json:"columns,omitempty"`
	Rows      [][]string    `json:"rows,omitempty"`
	Caption   string        `json:"caption,omitempty"`
	Button    *EmptyButton  `json:"button,omitempty"`
	Html      string        `json:"html,omitempty"`
	Height    int           `json:"height,omitempty"`
	Badges    []Badge       `json:"badges,omitempty"`
	Facts     []Fact        `json:"facts,omitempty"`
	Crumbs    []Crumb       `json:"crumbs,omitempty"`
	Entries   []TreeEntry   `json:"entries,omitempty"`
	Selected  string        `json:"selected,omitempty"`
	Expand    *Action       `json:"expand,omitempty"`
	Path      string        `json:"path,omitempty"`
	Language  string        `json:"language,omitempty"`
	StartLine int           `json:"start_line,omitempty"`
	Highlight *LineRange    `json:"highlight,omitempty"`
	Truncated bool          `json:"truncated,omitempty"`
	Load      *Action       `json:"load,omitempty"`
	// An https link to lines of this file on its site, {start} and {end} standing for the lines
	// (…/blob/<sha>/a.go#L{start}-L{end}).
	LineURL string `json:"line_url,omitempty"`
	// Go to definition (UI version 13): a name in the code chosen to follow it (⌘/Ctrl-click or ⌘/Ctrl+B on it; Alt+F7
	// for its usages) calls ui.action with action and values {path, line, column (1-based, in characters), word, intent:
	// definition or references}; ⌘[ (Ctrl+Alt+← elsewhere) calls it with {path, intent: back}. An older app leaves it
	// out.
	Navigate  *Action  `json:"navigate,omitempty"`
	OldPath   string   `json:"old_path,omitempty"`
	Status    string   `json:"status,omitempty"`
	Additions int      `json:"additions,omitempty"`
	Deletions int      `json:"deletions,omitempty"`
	Binary    bool     `json:"binary,omitempty"`
	Collapsed bool     `json:"collapsed,omitempty"`
	Hunks     []Hunk   `json:"hunks,omitempty"`
	Threads   []Thread `json:"threads,omitempty"`
	Comment   *Action  `json:"comment,omitempty"`
	// Fetch hidden lines of the file (UI version 5): values {path, side: new or old, from, to: a line or end}; the
	// extension answers with lines (ActionResult.lines), the page is not drawn again.
	Context *Action `json:"context,omitempty"`
	// The user has marked this file viewed.
	Viewed bool `json:"viewed,omitempty"`
	// Mark the file viewed or not: values {path, viewed: true or false}. Without it the app keeps viewed on the device,
	// by path and revision.
	MarkViewed *Action `json:"mark_viewed,omitempty"`
	// What this file's change is (a blob id): a viewed mark kept on the device holds for it only.
	Revision string `json:"revision,omitempty"`
	// A generated file or a lockfile: folded at first.
	Generated bool `json:"generated,omitempty"`
	// How alike a renamed file is to its old one, in percent.
	Similarity int `json:"similarity,omitempty"`
	// Add a comment to the pending review instead of sending it alone: values as comment's.
	Draft *Action `json:"draft,omitempty"`
	// The extension takes ```suggestion blocks in comments.
	Suggestions bool             `json:"suggestions,omitempty"`
	Comments    []Comment        `json:"comments,omitempty"`
	Resolved    bool             `json:"resolved,omitempty"`
	Reply       *Action          `json:"reply,omitempty"`
	Buttons     []ComposerButton `json:"buttons,omitempty"`
	Src         *ImageSource     `json:"src,omitempty"`
	// Read out, and shown when the picture does not load.
	Alt    string `json:"alt,omitempty"`
	Aspect string `json:"aspect,omitempty"`
	Fit    string `json:"fit,omitempty"`
	// Tapping does nothing (else it shows the picture full screen).
	NoZoom     bool        `json:"no_zoom,omitempty"`
	Tiles      []Tile      `json:"tiles,omitempty"`
	MaxColumns int         `json:"max_columns,omitempty"`
	Width      string      `json:"width,omitempty"`
	Nodes      []GraphNode `json:"nodes,omitempty"`
	Edges      []GraphEdge `json:"edges,omitempty"`
	Layout     string      `json:"layout,omitempty"`
	Direction  string      `json:"direction,omitempty"`
	// Ids of nodes whose children start folded. Once the person folds or unfolds one, the app keeps their choice for
	// this key.
	Folded []string `json:"folded,omitempty"`
	// A picture of the model for an older app (an image in its place) and for share as image. Without it an older app
	// gets a row per pin.
	Poster   *ImageSource `json:"poster,omitempty"`
	Camera   *SceneCamera `json:"camera,omitempty"`
	Shapes   []SceneShape `json:"shapes,omitempty"`
	Labels   []SceneLabel `json:"labels,omitempty"`
	Pins     []ScenePin   `json:"pins,omitempty"`
	Viewport *MapViewport `json:"viewport,omitempty"`
	Markers  []MapMarker  `json:"markers,omitempty"`
	Routes   []MapRoute   `json:"routes,omitempty"`
	Links    []MapLink    `json:"links,omitempty"`
	// When true, stays a non-interactive snapshot and does not open an interactive sheet.
	Static bool `json:"static,omitempty"`
	// When true (or when multiple routes/stops exist without a compact override), shows a companion route/stop list
	// beneath the map.
	ShowList bool `json:"show_list,omitempty"`
}

